    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==3 and p not in seen:
                        seen.add(p); stack.append(p)
            comps.append((min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells)))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # A marker inside a panel is recognized by lying within its bounds;
            # color 2 is an interruption in the otherwise solid color-3 panel.
            box=next((b for b in comps if b[0]<=r<=b[1] and b[2]<=c<=b[3]),None)
            if box is None:
                continue
            r0,r1,c0,c1=box
